sim_gesture &lt;- function(dur, mean_iv, gap = min_gap) {
  for (i in 1:1000) {
    t &lt;- cumsum(gap + rexp(ceiling(dur / gap) + 2, 1 / (mean_iv - gap)))
    t &lt;- t - runif(1) * t[1]
    iv &lt;- diff(t[t &lt;= dur])
    if (length(iv) &gt;= 1) return(iv)
  }
  NULL
}

null_slopes &lt;- function(d, nsim = 100) {
  gest &lt;- unique(d[, .(corpus, speaker, gid, gesture_dur, n_sub)])
  # n_sub + 1 is the number of peaks
  gest[, mean_iv := sum(gesture_dur) / sum(n_sub + 1), by = speaker]
  for (r in 1:3) {
    s &lt;- gest[, .(n = length(sim_gesture(gesture_dur, mean_iv))), by = gid]
    gest[s, on = "gid", n_sim := i.n]
    gest[, mean_iv := min_gap + (mean_iv - min_gap) * mean(n_sim) / mean(n_sub), by = speaker]
  }
  sapply(1:nsim, function(k) {
    s &lt;- gest[, .(sub_dur = sim_gesture(gesture_dur, mean_iv)), by = .(corpus, speaker, gid)]
    s[, n_sub := .N, by = gid]
    unname(fixef(paper_model(s))["x"])
  })
}




